def check(candidate) -> bool:
    try:
        N = 20000
        M = 1300
        if not isinstance(candidate, list) or len(candidate) < M:
            return False
        s = set()
        for v in candidate:
            if isinstance(v, bool) or not isinstance(v, int):
                return False
            if v < 1 or v > N or v in s:
                return False
            s.add(v)
        if len(s) < M:
            return False
        bits = 0
        pe = 0  # bit k set iff 2k in A
        po = 0  # bit k set iff 2k+1 in A
        for v in s:
            bits |= 1 << v
            if v % 2 == 0:
                pe |= 1 << (v // 2)
            else:
                po |= 1 << ((v - 1) // 2)
        # For each x in A, the set of y with 2y - x in A and 2y - x == x (mod 2)
        # is (pe << x/2) if x even, (po << (x+1)/2) if x odd.
        # A nontrivial 3-AP exists iff some such y != x lies in A.
        for x in s:
            if x % 2 == 0:
                mask = pe << (x // 2)
            else:
                mask = po << ((x + 1) // 2)
            hit = mask & bits
            hit &= ~(1 << x)
            if hit:
                return False
        return True
    except Exception:
        return False
